/bin/zsh -lc "cat > benchmark/solution.ail <<'EOF'
module benchmark/solution
import std/net (httpRequest)
import std/json (encode, jo, kv, js, jint)

export func main() -> () "'! {IO, Net} {
  let body = encode(jo([kv("message", js("Hello from AILANG")), kv("count", jint(42))]));
  match httpRequest("POST", "http://127.0.0.1:7655", [{name: "X-Test-Header", value: "value123"}, {name: "Content-Type", value: "application/json"}], body) {
    Ok(response) => println(show(response.status)),
    Err(_) => println("0")
  }
}
EOF
ailang run --entry main --caps Net,IO --net-allow-http --net-allow-localhost benchmark/solution.ail'

